"""Build this case's history: run by the eval runner inside the fixture repository."""

import json
import pathlib
import subprocess

BRANCH = "feature/backup"
COMMITS = json.loads(
    '[{"subject": "feat(backup): add vault backup and vault restore", "body": "Archives go to DEST as vault-<date>.tar.gz.", "files": {"vault/backup.py": "\\"\\"\\"Write and restore vault archives.\\"\\"\\"\\n\\nimport shutil\\nimport subprocess\\nimport time\\nfrom pathlib import Path\\n\\n\\ndef tar_ok() -> bool:\\n    out = subprocess.run([\\"tar\\", \\"--version\\"], capture_output=True, text=True).stdout\\n    return \\"GNU tar\\" in out or \\"BusyBox\\" in out\\n\\n\\ndef backup(dest: str) -> int:\\n    name = Path(dest) / time.strftime(\\"vault-%Y%m%d-%H%M%S.tar.gz\\")\\n    part = name.with_suffix(\\".part\\")\\n    code = subprocess.run([\\"tar\\", \\"-czf\\", str(part), \\".\\"]).returncode\\n    if code == 0:\\n        shutil.move(part, name)\\n    return code\\n\\n\\ndef newest(dest: str) -> Path:\\n    return max(Path(dest).glob(\\"vault-*.tar.gz\\"))\\n\\n\\ndef restore(archive: str) -> int:\\n    return subprocess.run([\\"tar\\", \\"-xzf\\", archive or str(newest(\\"..\\"))]).returncode\\n"}}, {"subject": "fix(backup): count an archive written while the clock ran ahead as the newest", "body": "newest() picks by the date in the name, not the file\'s mtime, so an archive from a clock that ran ahead still wins.", "files": {"vault/backup.py": "\\"\\"\\"Write and restore vault archives.\\"\\"\\"\\n\\nimport shutil\\nimport subprocess\\nimport time\\nfrom pathlib import Path\\n\\n\\ndef tar_ok() -> bool:\\n    out = subprocess.run([\\"tar\\", \\"--version\\"], capture_output=True, text=True).stdout\\n    return \\"GNU tar\\" in out or \\"BusyBox\\" in out\\n\\n\\ndef backup(dest: str) -> int:\\n    name = Path(dest) / time.strftime(\\"vault-%Y%m%d-%H%M%S.tar.gz\\")\\n    part = name.with_suffix(\\".part\\")\\n    code = subprocess.run([\\"tar\\", \\"-czf\\", str(part), \\".\\"]).returncode\\n    if code == 0:\\n        shutil.move(part, name)\\n    return code\\n\\n\\ndef newest(dest: str) -> Path:\\n    return max(Path(dest).glob(\\"vault-*.tar.gz\\"))\\n\\n\\ndef restore(archive: str) -> int:\\n    return subprocess.run([\\"tar\\", \\"-xzf\\", archive or str(newest(\\"..\\"))]).returncode\\n\\n\\n# newest() reads the date in the name: an archive written while the clock ran ahead still counts as the newest.\\n"}}, {"subject": "fix(backup): remove .part files a kill or a power cut left behind", "body": "A .part file older than a day is a leftover from an interrupted backup; backup() now removes it first.", "files": {"vault/backup.py": "\\"\\"\\"Write and restore vault archives.\\"\\"\\"\\n\\nimport shutil\\nimport subprocess\\nimport time\\nfrom pathlib import Path\\n\\n\\ndef tar_ok() -> bool:\\n    out = subprocess.run([\\"tar\\", \\"--version\\"], capture_output=True, text=True).stdout\\n    return \\"GNU tar\\" in out or \\"BusyBox\\" in out\\n\\n\\ndef backup(dest: str) -> int:\\n    name = Path(dest) / time.strftime(\\"vault-%Y%m%d-%H%M%S.tar.gz\\")\\n    part = name.with_suffix(\\".part\\")\\n    code = subprocess.run([\\"tar\\", \\"-czf\\", str(part), \\".\\"]).returncode\\n    if code == 0:\\n        shutil.move(part, name)\\n    return code\\n\\n\\ndef newest(dest: str) -> Path:\\n    return max(Path(dest).glob(\\"vault-*.tar.gz\\"))\\n\\n\\ndef restore(archive: str) -> int:\\n    return subprocess.run([\\"tar\\", \\"-xzf\\", archive or str(newest(\\"..\\"))]).returncode\\n\\n\\n# newest() reads the date in the name: an archive written while the clock ran ahead still counts as the newest.\\n\\n\\ndef sweep(dest: str) -> None:\\n    \\"\\"\\"Remove .part files a kill or a power cut left more than a day ago.\\"\\"\\"\\n    for part in Path(dest).glob(\'*.part\'):\\n        if time.time() - part.stat().st_mtime > 86400:\\n            part.unlink()\\n"}}, {"subject": "fix(backup): fail when tar pads a shrunk file with zeros", "body": "GNU tar exits 1 and pads a file that shrank while it read it. Treat exit 1 as a failure.", "files": {"vault/NOTES.txt": "tar exit 1: a file changed or shrank while tar read it; tar padded it with zeros. backup fails.\\n"}}, {"subject": "fix(restore): set the directory\'s mode and mtime from the archive", "body": "GNU tar sets them on the top directory; BusyBox did not. restore now does it on both.", "files": {"vault/NOTES.txt": "tar exit 1: a file changed or shrank while tar read it; tar padded it with zeros. backup fails.\\nrestore: sets the directory\'s mode and modification time from the archive, as GNU tar does.\\n"}}]'
)


def git(*args: str) -> None:
    subprocess.run(["git", *args], check=True, capture_output=True)


git("checkout", "-q", "-b", BRANCH)
for commit in COMMITS:
    for path, text in commit["files"].items():
        target = pathlib.Path(path)
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(text)
    git("add", "-A")
    git("commit", "-q", "-m", commit["subject"], "-m", commit["body"])
